# Toast

> Global notifications with actions and live-region semantics.

- Status: available
- Route: /components/toast
- Package: @kikita-labs/ui@2.0.0
- Import: KuiToast from @kikita-labs/ui
- Source docs: https://github.com/kikita-labs/kikita-ui/blob/v2.0.0/docs/toast.md

## Install

```bash
pnpm add @kikita-labs/ui
ng add @kikita-labs/ui
```

## Usage

```ts
@Component({ ... })
export class MyComponent {
  private toast = kuiToast();

  save() {
    this.api.save().subscribe({
      next: () =>
        this.toast.open({ title: 'Saved', appearance: 'success' }),
      error: () =>
        this.toast.open({ title: 'Failed', appearance: 'danger', persistent: true }),
    });
  }
}
```

## Examples

Rendered at /components/toast:

### basic-toast-example

#### basic-toast-example.html

```html
<div class="basic-toast-example">
  @for (trigger of triggers; track trigger.appearance) {
    <button kuiButton type="button" shape="soft" (click)="show(trigger.appearance)">
      {{ trigger.label }}
    </button>
  }
</div>
```

#### basic-toast-example.ts

```ts
import { Component } from '@angular/core';

import { KuiButton, kuiToast, type KuiToastAppearance } from '@kikita-labs/ui';

interface ToastTrigger {
  readonly label: string;
  readonly appearance: KuiToastAppearance;
}

@Component({
  selector: 'app-basic-toast-example',
  imports: [KuiButton],
  templateUrl: './basic-toast-example.html',
  styleUrl: './basic-toast-example.scss',
})
export class BasicToastExample {
  private readonly toast = kuiToast();

  protected readonly triggers: readonly ToastTrigger[] = [
    { label: 'Neutral', appearance: 'neutral' },
    { label: 'Success', appearance: 'success' },
    { label: 'Warning', appearance: 'warning' },
    { label: 'Danger', appearance: 'danger' },
    { label: 'Info', appearance: 'info' },
  ];

  protected show(appearance: KuiToastAppearance): void {
    this.toast.open({
      title: this.titleFor(appearance),
      message: this.messageFor(appearance),
      appearance,
      persistent: appearance === 'danger',
    });
  }

  private titleFor(appearance: KuiToastAppearance): string {
    switch (appearance) {
      case 'success':
        return 'Saved';
      case 'danger':
        return 'Failed to save';
      case 'warning':
        return 'Check your input';
      case 'info':
        return 'Heads up';
      default:
        return 'Notification';
    }
  }

  private messageFor(appearance: KuiToastAppearance): string {
    switch (appearance) {
      case 'success':
        return 'Your changes have been saved.';
      case 'danger':
        return 'Check your connection and try again.';
      case 'warning':
        return 'Some fields still need your attention.';
      case 'info':
        return 'A new version is available.';
      default:
        return 'Something happened.';
    }
  }
}
```

#### basic-toast-example.scss

```scss
.basic-toast-example {
  display: flex;
  flex-wrap: wrap;
  gap: var(--kui-space-3, 12px);
}
```

### toast-action-example

#### toast-action-example.html

```html
<button kuiButton type="button" shape="outline" appearance="danger" (click)="deleteMessage()">
  Delete message
</button>
```

#### toast-action-example.ts

```ts
import { Component, DestroyRef, inject } from '@angular/core';

import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

import { KuiButton, kuiToast } from '@kikita-labs/ui';

@Component({
  selector: 'app-toast-action-example',
  imports: [KuiButton],
  templateUrl: './toast-action-example.html',
  styleUrl: './toast-action-example.scss',
})
export class ToastActionExample {
  private readonly toast = kuiToast();
  private readonly destroyRef = inject(DestroyRef);

  protected deleteMessage(): void {
    const ref = this.toast.open({
      title: 'Message deleted',
      actionLabel: 'Undo',
      duration: 6000,
    });

    ref.action$.pipe(takeUntilDestroyed(this.destroyRef)).subscribe(() => this.undoDelete());
  }

  private undoDelete(): void {
    this.toast.open({ title: 'Delete undone', appearance: 'success' });
  }
}
```

#### toast-action-example.scss

```scss
:host {
  display: block;
}
```

### toast-position-example

#### toast-position-example.html

```html
<div class="toast-position-example">
  @for (position of positions; track position) {
    <button kuiButton type="button" shape="soft" size="sm" (click)="show(position)">
      {{ position }}
    </button>
  }
</div>
```

#### toast-position-example.ts

```ts
import { Component } from '@angular/core';

import { KuiButton, kuiToast, type KuiToastPosition } from '@kikita-labs/ui';

@Component({
  selector: 'app-toast-position-example',
  imports: [KuiButton],
  templateUrl: './toast-position-example.html',
  styleUrl: './toast-position-example.scss',
})
export class ToastPositionExample {
  private readonly toast = kuiToast();

  protected readonly positions: readonly KuiToastPosition[] = [
    'top-start',
    'top-center',
    'top-end',
    'bottom-start',
    'bottom-center',
    'bottom-end',
  ];

  protected show(position: KuiToastPosition): void {
    this.toast.setPosition(position);
    this.toast.open({
      title: position,
      message: 'This toast opened at the selected position.',
    });
  }
}
```

#### toast-position-example.scss

```scss
.toast-position-example {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--kui-space-2, 8px);
  max-inline-size: 420px;
}
```

## API

| Name | Type | Default | Description |
| --- | --- | --- | --- |
| title | string | - | Required headline text passed to open(). |
| message | string \| undefined | - | Optional supporting text below the title. |
| appearance | 'neutral' \| 'success' \| 'warning' \| 'danger' \| 'info' | 'neutral' | Visual intent. Controls the accent bar and icon color; neutral renders no icon. |
| actionLabel | string \| undefined | - | Label for the inline action button. Clicking it emits once on KuiToastRef.action$. |
| duration | number | 5000 | Auto-dismiss delay in ms. Ignored when persistent is true. App-wide default overridable via defaults.toast. |
| persistent | boolean \| Signal<boolean> | false | Keeps the toast open until it is closed explicitly. A signal can start or pause the auto-dismiss timer reactively. |
| closable | boolean | true | Shows the close button. App-wide default overridable via defaults.toast. |
| showIcon | boolean | true | Shows the appearance icon. App-wide default overridable via defaults.toast. |
| showProgress | boolean | false | Shows a progress bar tracking time until auto-dismiss. App-wide default overridable via defaults.toast. |
| kuiToast() | () => KuiToast | - | Inject-function returning a reusable opener bound to the current injector scope. Call once per component; prefer over injecting KuiToast directly. |
| KuiToast.open(config) | (config: KuiToastConfig) => KuiToastRef | - | Shows a toast notification and returns a ref for programmatic control. |
| KuiToast.setPosition(position) | (position: KuiToastPosition) => void | - | Changes the shared toast region position at runtime. Intended for interactive demos; prefer defaults.toast for app-level configuration. |
| KuiToastRef.close() | () => void | - | Closes this toast programmatically and plays the exit animation. |
| KuiToastRef.id | number | - | Stable identifier for this toast within its owning toast service. |
| KuiToastRef.update(config) | (config: Partial<KuiToastConfig>) => void | - | Updates this toast in place and re-evaluates its auto-dismiss timer. |
| KuiToastRef.closed$ | Observable<void> | - | Emits once after the close animation finishes, then completes. |
| KuiToastRef.action$ | Observable<void> | - | Emits once when the action button is clicked, then completes. |
| KuiToast.dismiss(id) | (id: number) => void | - | Dismisses one toast created by this service using its stable reference id. |
| KuiToast.dismissAll() | () => void | - | Dismisses all active toasts created by this service. |
| provideKuiDefaults({ toast }) | (defaults: KuiComponentDefaults) => Provider | - | App or route-level provider for toast defaults: position, duration, maxVisible, showProgress, closable, showIcon and closeIcon. |
| position | 'top-start' \| 'top-center' \| 'top-end' \| 'bottom-start' \| 'bottom-center' \| 'bottom-end' | 'bottom-center' | Global region position. Set app-wide via defaults.toast, or at runtime via KuiToast.setPosition for demos. |
| maxVisible | number | 3 | Max simultaneous toasts, set via defaults.toast. The oldest visible toast is evicted when exceeded. It follows runtime changes of the default. |
| KuiToastOptions | interface | - | Shape of defaults.toast: position, duration, maxVisible, showProgress, closable, showIcon and closeIcon. |

## Accessibility

Rendered documentation, interactive examples, and the playground live at the HTML route above.

## Playground

Available at /components/toast/playground.

